"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[7497],{2218(e){e.exports=JSON.parse('{"title":"\ub3d9\uc2dc\uc131, \ubcd1\ub82c\uc131\uc744 JavaScript \ub0b4\uc5d0\uc11c \uc774\ud574\ud558\uae30","date":"2024-09-26","coverUrl":null,"html":"<h2 data-notion-block-id=\\"5fea8afd-2d28-49ba-94a5-4545556f37b5\\" id=\\"5fea8afd-2d28-49ba-94a5-4545556f37b5\\">\ub3d9\uc2dc\uc131, \ubcd1\ub82c\uc131\uc744 JavaScript \ub0b4\uc5d0\uc11c \uc774\ud574\ud558\uae30</h2><a href=\\"https://www.rugu.dev/en/blog/concurrency-and-parallelism/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.rugu.dev/en/blog/concurrency-and-parallelism/</a><p data-notion-block-id=\\"109e548d-8a8e-8090-a5eb-d0d2483d1906\\"><b>\uc2ec\uc724\uc12d</b>: CS\uc9c0\uc2dd\uc5d0\uc11c \ub9ce\uc774 \ud5f7\uac08\ub9ac\ub294 \uac1c\ub150\uc778 \ub3d9\uc2dc\uc131, \ubcd1\ub82c\uc131\uc744 \uc18c\uac1c\ud558\uace0 NodeJS\uc5d0\uc11c \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \ub450 \uac1c\ub150\uc744 \uad6c\ud604\ud558\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ube0c\ub77c\uc6b0\uc800 API, \ub610\ub294 Web Worker \uac1c\ub150\ub3c4 \ube44\uc2b7\ud558\uac8c \uc801\uc6a9 \uac00\ub2a5\ud558\ub2c8 \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><p data-notion-block-id=\\"216f65b1-29f4-4cad-b52b-f3ea7671af3c\\"><b>\uae40\ub300\uad00</b>: \ub3d9\uc2dc\uc131\uacfc \ubcd1\ub82c\uc131\uc5d0 \ub300\ud55c \uac1c\ub150\uc744 NodeJS\uc5d0\uc11c \uc608\uc81c\ub97c \ud1b5\ud574 \uad6c\ubd84\uc744 \ubcf4\uc5ec\uc8fc\ub294 \ubd80\ubd84\uc5d0\uc11c \ub9ce\uc740 \uc774\ud574\uac00 \ub418\ub294 \uae00\uc774\uc5c8\uc2b5\ub2c8\ub2e4. \ube44\ub3d9\uae30 \ucc98\ub9ac\uc5d0 \uc788\uc5b4\uc11c \ub3d9\uc2dc\uc131\uacfc \ubcd1\ub82c\uc131\uc5d0 \ub300\ud55c React \ucf54\ub4dc \uc791\uc131\uc744 \uace0\ubbfc\ud558\uc2e0\ub2e4\uba74 <a href=\\"https://youtu.be/FvRtoViujGg\\">\ud1a0\uc2a4\uc5d0\uc11c \ubc1c\ud45c\ud55c \ube44\ub3d9\uae30 \ucc98\ub9ac \uc601\uc0c1</a>\uc744 \ubcf4\uc2dc\ub294 \uac83\uc744 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"109e548d-8a8e-8079-8c80-edd09db9fe25\\" id=\\"109e548d-8a8e-8079-8c80-edd09db9fe25\\">Tanstack Router\uc758 TypeScript \uc131\ub2a5 \ucd5c\uc801\ud654\ud558\uae30</h2><a href=\\"https://tanstack.com/blog/tanstack-router-typescript-performance\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tanstack.com/blog/tanstack-router-typescript-performance</a><p data-notion-block-id=\\"109e548d-8a8e-80a3-9173-e347c9c39b8e\\"><b>\uc2ec\uc724\uc12d</b>: <a href=\\"https://ones-to-watch.ethansup.net/news/post/39799967-7996-485e-bb90-8662186cc013#08be7f66-9813-4aa6-9a07-d6711dd603c2\\">\ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8 \uac80\uc0ac \ubca4\uce58\ub9c8\ud06c \uacfc\uc815</a>\uacfc \ube44\uc2b7\ud558\uac8c \ud0c0\uc785 \uccb4\ud06c \uacfc\uc815\uc744 \ucd94\uc801\ud558\uace0 \ucd5c\uc801\ud654\uacfc\uc815\uc744 \ub2f4\uc740 \uae00\uc785\ub2c8\ub2e4. \ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8 \uc720\ud615 \ucd94\ub860 \ubcd1\ubaa9\uc740 \ub9e4\uc6b0 \uc9c0\uc5fd\uc801\uc778 \ubd80\ubd84\uc774\uc9c0\ub9cc \ubcd1\ubaa9 \ud604\uc0c1\uc744 \ucc3e\uae30 \uc704\ud574 \ubd84\ub9ac\ud558\uace0 \ud574\uacb0\ud558\uae30 \uc704\ud574 \ud574\uacb0\ud558\ub294 \uc5ec\ub7ec \ubc29\ubc95\uc744 \ubaa8\ub450 \uc0dd\uac01\ud574\ubcf4\ub294 \ubc29\uc2dd\uc740 \uc5ec\ub7ec \ubc29\uba74\uc73c\ub85c \uc801\uc6a9\ud560\ub9cc\ud569\ub2c8\ub2e4. </p><h2 data-notion-block-id=\\"63d1ea08-dbc0-4486-9114-797028bfa3c9\\" id=\\"63d1ea08-dbc0-4486-9114-797028bfa3c9\\">React \ucd94\uc0c1\ud654\uc5d0\uc11c \uac00\uc7a5 \ub9ce\uc774 \uc2e4\uc218\ud558\ub294 \ubd80\ubd84</h2><a href=\\"https://darios.blog/posts/using-callbacks-in-react\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://darios.blog/posts/using-callbacks-in-react</a><p data-notion-block-id=\\"109e548d-8a8e-8041-8b66-de65bdcd4954\\"><b>\uc2ec\uc724\uc12d</b>: <code>setState</code>\ub97c \uc9c1\uc811 \uc804\ub2ec\ud558\uc9c0 \ub9d0\ub77c\ub294 \uac04\ub2e8\ud55c \uae00\uc774\uc9c0\ub9cc, \ucc98\uc74c React\ub97c \uc811\ud588\uc744 \uacbd\uc6b0 \ub9ce\uc774 \uc2e4\uc218\ud558\ub294 \ubd80\ubd84\uc785\ub2c8\ub2e4. <code>setState</code>\ub97c \uc804\ub2ec\ud558\uba74 props\ub294 \uc904\uc5b4\ub4e4\uc9c0\ub9cc, \uacb0\ud569\uc131\uc740 \uc99d\uac00\ud574 \uc218\uc815\ud558\uae30 \uc5b4\ub824\uc6cc\uc9c0\uae30\ub3c4 \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"109e548d-8a8e-8033-a90c-e3ad6ea49f73\\" id=\\"109e548d-8a8e-8033-a90c-e3ad6ea49f73\\"><code>height: auto;</code>\uac00 \uc560\ub2c8\uba54\uc774\uc158 \uc791\ub3d9\uc774 \uc548\ub418\uc694</h2><a href=\\"https://developer.chrome.com/docs/css-ui/animate-to-height-auto/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://developer.chrome.com/docs/css-ui/animate-to-height-auto/</a><p data-notion-block-id=\\"109e548d-8a8e-800a-9295-c615d509b2df\\"><b>\uc2ec\uc724\uc12d</b>: \uc790\uc8fc \ub9c8\uc8fc\uce58\ub294 \uc0c1\ud669\uc774\uba70, \ud0a4\uc6cc\ub4dc \uae00\uc785\ub2c8\ub2e4. <code>interpolate-size</code>\ub77c\ub294 \uc0c8\ub85c\uc6b4 \uae30\ub2a5\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc774\uc9c0\ub9cc, <a href=\\"https://developer.chrome.com/blog/performant-expand-and-collapse?hl=ko\\">CSS \uc0bd\uc785\uc774\ub098, JS animation API\ub85c\ub3c4 \uad6c\ud604</a>\ud560 \uc218 \uc788\uace0, \ucd5c\uc2e0 API\uc774\uae30 \ub54c\ubb38\uc5d0 polyfill \uad6c\ud604\uc740 \ud544\uc694\ud574\ubcf4\uc774\ub124\uc694.</p><h2 data-notion-block-id=\\"ae196eb5-b334-4727-ab5d-6d9d1922d398\\" id=\\"ae196eb5-b334-4727-ab5d-6d9d1922d398\\">React 19 \uce58\ud2b8\uc2dc\ud2b8</h2><a href=\\"https://www.epicreact.dev/react-19-cheatsheet\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.epicreact.dev/react-19-cheatsheet</a><p data-notion-block-id=\\"109e548d-8a8e-807b-ac92-c7fc01075796\\">React 19\uc758 \uc2e0 \uae30\ub2a5\ub4e4\uc744 \ud55c \ub208\uc5d0 \ubcfc \uc218 \uc788\ub294 \uce58\ud2b8\uc2dc\ud2b8\uc785\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/298d028d8e9c4d13b87a3ae9f00712fa#f141d899-2d6c-46b8-888f-be0cdeab6882\\">React 16.8 \uadf8 \uc774\ud6c4</a> \uae00\uc774\ub098 <a href=\\"https://ones-to-watch.ethansup.net/news/post/cd29f440-15b4-4145-a8d4-ec9da1e43ce9#02e5f692-2234-437b-8ede-c28bde84bb48\\">Vercel\uc758 React 19 \uc18c\uac1c \uae00</a>\ub3c4 \uac19\uc774 \ubcf4\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"109e548d-8a8e-8055-9c45-e44c352ad2b4\\" id=\\"109e548d-8a8e-8055-9c45-e44c352ad2b4\\">RTT\uac00 \ubb34\uc5c7\uc774\uace0, \uc5b4\ub5bb\uac8c \ub300\uc751\ud574\uc57c \ud558\uc8e0?</h2><a href=\\"https://csswizardry.com/2024/09/optimising-for-high-latency-environments/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://csswizardry.com/2024/09/optimising-for-high-latency-environments/</a><p data-notion-block-id=\\"109e548d-8a8e-803a-ae7e-e7177d66e174\\"><b>\uc2ec\uc724\uc12d</b>: \uc0dd\uc18c\ud55c \uac1c\ub150\uc778 RTT(\uc655\ubcf5 \uc2dc\uac04)\uc5d0 \ub300\ud574 \uc18c\uac1c\ud558\uace0, \ud574\uacb0\ud558\ub294 \ubc29\ubc95\uacfc \uae30\uc220\ub4e4\uc744 \uc18c\uac1c\ub97c \ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc9c0\ud45c\ub294 \ub2e8\uc21c\ud558\uac8c \ud558\ub098\uc9c0\ub9cc, <a href=\\"https://ones-to-watch.ethansup.net/news/post/427a9c3c-eab8-4c52-b1c8-9036c2552ded#727fc4cc-799f-4801-bd38-9d339cf8d25a\\">TTFB \ucd5c\uc801\ud654 \uac00\uc774\ub4dc</a>\uc640 \uac19\uc774 \uc778\ud504\ub77c\uc640 \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc758 \uc5ec\ub7ec \ubd80\ubd84\uc744 \uc0b4\ud3b4\ubd10\uc57c \ud558\ubbc0\ub85c, \uc9c0\ud45c\ub97c \uc778\uc9c0\ud558\uace0 \uc5ec\ub7ec \ubc29\uc2dd\uc744 \uc0dd\uac01\ud558\ub294 \uac83\uc774 \uc88b\uc544\ubcf4\uc785\ub2c8\ub2e4. </p><h2 data-notion-block-id=\\"109e548d-8a8e-80aa-b1ba-ceefdc51f879\\" id=\\"109e548d-8a8e-80aa-b1ba-ceefdc51f879\\">SPA\uc5d0\uac8c \uc9c0\uc5f0\ub85c\ub529\uc740 \uc88b\uc740\uac00?</h2><a href=\\"https://reacttraining.com/blog/spa-lazy-loading-pitfalls\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://reacttraining.com/blog/spa-lazy-loading-pitfalls</a><p data-notion-block-id=\\"109e548d-8a8e-8028-ab00-e9b257e730ed\\"><b>\uc2ec\uc724\uc12d</b>: SPA\uc5d0\uc11c \uc9c0\uc5f0 \ub85c\ub529\uc740 \ubc88\ub4e4 \ud06c\uae30\ub97c \uc904\uc778\ub2e4\ub294 \uc810\uc5d0\uc11c \uc88b\uc9c0\ub9cc, \uc0c1\ud669\uc5d0 \ub530\ub77c\uc11c \uc88b\uc9c0 \uc54a\uc740 \uacbd\uc6b0\uac00 \uc0dd\uae41\ub2c8\ub2e4. \uc774 \uae00\uc740 <code>loader</code>\ub97c \uac19\uc774 \uc0ac\uc6a9\ud560 \uacbd\uc6b0 \ubcd1\ub82c\ub85c \ub85c\ub529\ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc5d0\uc11c \uc88b\uc9c0 \uc54a\ub2e4\ub294 \uac83\uc744 \uc124\uba85\ud558\uc9c0\ub9cc, \uc774\uc678\uc5d0\ub3c4 \ub2e4\ub978 \uc0c1\ud669\uc5d0\uc11c waterfall\uc774 \ubc1c\uc0dd\ud560 \uc218 \uc788\uc73c\ubbc0\ub85c \uc801\uc808\ud558\uac8c \uc0ac\uc6a9\ud574\uc57c \ud569\ub2c8\ub2e4.</p><p data-notion-block-id=\\"932a7b4a-f9cb-476d-9f39-8028b6db96ae\\"><b>\uae40\ub300\uad00: </b>SPA\uc5d0\uc11c \uc9c0\uc5f0 \ub85c\ub529\uc744 \ud1b5\ud574 \ubc88\ub4e4 \ud06c\uae30\ub97c \uc904\uc77c \uc218 \uc788\uc9c0\ub9cc, loader\uc640 \uc77c\ubd80 \ucef4\ud3ec\ub10c\ud2b8\uc758 \ubd84\ub9ac\ub97c \ud1b5\ud574 \ubcd1\ub82c \ub85c\ub529\uc744 \ucc98\ub9ac\ud574\uc57c \ud55c\ub2e4\ub294 \uc778\uc0ac\uc774\ud2b8\ub97c \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.  \uc9c0\uc5f0 \ub85c\ub529\uc5d0 \ub300\ud574\uc11c \uc131\ub2a5\uc801\uc73c\ub85c\ub098, \uc0ac\uc6a9\uc790 \uacbd\ud5d8\uc5d0\uc11c \ubc18\ub4dc\uc2dc \ud544\uc694\ud55c\uc9c0\ub97c \uc798 \uac80\ud1a0\ud558\uace0 \uc0ac\uc6a9\ud574\uc57c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"109e548d-8a8e-8083-963e-c36529586975\\" id=\\"109e548d-8a8e-8083-963e-c36529586975\\">Remix\uc758 \ubcf5\uc7a1\ud55c \ub77c\uc6b0\ud305 \uc791\ub3d9 \ubc29\uc2dd</h2><a href=\\"https://www.udohjeremiah.com/blog/how-remix-flat-file-based-routing-works\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.udohjeremiah.com/blog/how-remix-flat-file-based-routing-works</a><p data-notion-block-id=\\"109e548d-8a8e-80cf-8666-e239aa27d4ba\\">Remix\ub294 \ub77c\uc6b0\ud305\uc758 \ubc29\uc2dd\uc740 \uc5ec\ub7ec \uc124\uc815\ubc29\uc2dd\uc774 \uc788\uace0, \ub300\uaddc\ubaa8\ub85c \ubc1c\uc804\ub418\uba74 <a href=\\"https://remix.run/docs/en/main/file-conventions/routes#disclaimer\\">\uc5b4\ub5a4 \ucee8\ubca4\uc158\uc744 \uc0ac\uc6a9\ud558\ub4e0 \ud63c\ub780\uc2a4\ub7ec\uc6cc\uc9c4\ub2e4\ub294 \uac83\uc744 \uac15\uc870</a>\ud569\ub2c8\ub2e4. \uadf8\ub9ac\uace0 Flat \ud30c\uc77c \uae30\ubc18 \ub77c\uc6b0\ud305 \ubc29\uc2dd\uc740 \uc9c1\uad00\uc801\uc774\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc740 \uc774 \ubc29\uc2dd\uc744 \uc27d\uac8c \uc774\ud574\ud560 \uc218 \uc788\ub3c4\ub85d \ub3d5\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"109e548d-8a8e-80a3-bb2a-f6380b072bbf\\" id=\\"109e548d-8a8e-80a3-bb2a-f6380b072bbf\\">TypeScript\uc5d0\uc11c \ubc30\uc5f4 \uc548 \uac1d\uccb4\uc758 \ud504\ub85c\ud37c\ud2f0\uc758 \ud0c0\uc785 \uc5bb\uae30</h2><a href=\\"https://www.totaltypescript.com/get-the-type-of-an-array-element\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.totaltypescript.com/get-the-type-of-an-array-element</a><p data-notion-block-id=\\"109e548d-8a8e-8060-8e76-de075d2d0ac3\\">\uc5ec\ub7ec \uad70\ub370\uc5d0\uc11c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \uc88b\uc740 \ud2b8\ub9ad\uc778 \ubc30\uc5f4 \uc548 \uac1d\uccb4\uc758 \ud504\ub85c\ud37c\ud2f0\uc758 \ud0c0\uc785\uc744 \uc5bb\ub294 \ubc29\ubc95\uc744 \uc124\uba85\ud55c \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"109e548d-8a8e-80b3-81d6-c84417f4ea23\\" id=\\"109e548d-8a8e-80b3-81d6-c84417f4ea23\\">Infinite Query\ub294 \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uac00</h2><a href=\\"https://tkdodo.eu/blog/how-infinite-queries-work\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tkdodo.eu/blog/how-infinite-queries-work</a><p data-notion-block-id=\\"109e548d-8a8e-804e-8e38-c14c4838cfe4\\"><a href=\\"https://tkdodo.eu/blog/inside-react-query\\">Tanstack Query\ub294 \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uac00</a>\uc5d0 \uc774\uc5b4 Infinite Query\uc758 \ub3d9\uc791\uacfc\uc815\uacfc \uac00\uc9c0\uace0 \uc788\ub358 \ubc84\uadf8\ub97c \uc218\uc815\ud558\ub294 \uacfc\uc815\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ubc84\uadf8\ub294 \uac04\ub2e8\ud55c \ud074\ub85c\uc800 \uc120\uc5b8 \ubb38\uc81c\uc600\uc9c0\ub9cc, Tanstack Query\uc758 \uacc4\uce35\uc744 \ud55c\ubc88 \ub354 \uc0c1\uae30\ud560 \uc218 \uc788\ub294 \uc88b\uc740 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"e4d2ea6b-2f84-44c3-b302-28ec06dad079\\" id=\\"e4d2ea6b-2f84-44c3-b302-28ec06dad079\\">JavaScript to C API\uc758 \uc5ed\uc0ac</h2><a href=\\"https://bun.sh/blog/compile-and-run-c-in-js\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://bun.sh/blog/compile-and-run-c-in-js</a><p data-notion-block-id=\\"109e548d-8a8e-80ce-8d28-f1265727f844\\">C \ud504\ub85c\uadf8\ub7a8\uc744 \ucef4\ud30c\uc77c\ud558\uace0 JS\uc5d0\uc11c \uc2e4\ud589\ud558\ub824\ub294 \uc5ed\uc0ac\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. bun \uae30\ub2a5\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc774\uc9c0\ub9cc, \ucd08\ubc18 \ubd80\uc758 \uc5ed\uc0ac\ub294 \uc77d\uc744\ub9cc \ud558\ub124\uc694!</p><h2 data-notion-block-id=\\"109e548d-8a8e-8095-8f84-cc6dee8c2e38\\" id=\\"109e548d-8a8e-8095-8f84-cc6dee8c2e38\\">JS\ub85c \ucc28 \ud574\ud0b9\ud558\uae30</h2><a href=\\"https://charliegerard.dev/blog/replay-attacks-javascript-hackrf/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://charliegerard.dev/blog/replay-attacks-javascript-hackrf/</a><p data-notion-block-id=\\"021c10ad-771f-44ef-a198-947530c34ad7\\">WebUSB API\uc640 \uc790\ub3d9\ucc28 \ud0a4\uc758 \uc791\ub3d9 \ubc29\uc2dd\uc744 \uac04\ub2e8\ud558\uac8c \uc124\uba85\ud558\ub294 \ud765\ubbf8\ub85c\uc6b4 \uae00\uc785\ub2c8\ub2e4. \uac00\ubccd\uac8c \uc77d\uc5b4\ubcf4\uae30 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"ed0c398d-c7d8-475d-b44e-e249728f3373\\" id=\\"ed0c398d-c7d8-475d-b44e-e249728f3373\\">\ub354 \ub098\uc740 <code>try...catch</code>\uad6c\ubb38 \ub9cc\ub4e4\uae30</h2><a href=\\"https://alexjpate.com/posts/cleaner-promises-with-safe-await\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://alexjpate.com/posts/cleaner-promises-with-safe-await</a><p data-notion-block-id=\\"109e548d-8a8e-80cf-bfa4-c6a1777d8daf\\"><code>try...catch</code>\uad6c\ubb38\uc774 \uc720\uc9c0\ubcf4\uc218\ud558\uae30 \uc5b4\ub824\uc6b4 \uc774\uc720\uc640 (\ub2e4\ub978 \uc5b8\uc5b4\uc758 \uc624\ub958 \ucc98\ub9ac \ud328\ud134\uc744 \ud1b5\ud574) \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ud1b5\ud574 \uc624\ub958 \ucc98\ub9ac\ub97c \ubcf4\uae30 \uc27d\uac8c \ub9cc\ub4dc\ub294 \ubc29\ubc95\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. \uac04\ub2e8\ud55c \ub77c\uc774\ube0c\ub7ec\ub9ac\uc774\ubbc0\ub85c \uc624\ub958\ucc98\ub9ac\uc5d0 \ub300\ud574 \uc5b4\ub824\uc6c0\uc744 \uacaa\ub294 \uacbd\uc6b0 \uc120\ud0dd\uc9c0 \uc911 \ud558\ub098\uac00 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"109e548d-8a8e-8034-8c1e-fb49ace6e228\\" id=\\"109e548d-8a8e-8034-8c1e-fb49ace6e228\\">\uc0c8\ub85c\uc6b4 \uc81c\ud488 \uc18c\uc2dd?</h2><a href=\\"https://astro.build/blog/astro-5-beta/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://astro.build/blog/astro-5-beta/</a><a href=\\"https://webkit.org/blog/15865/webkit-features-in-safari-18-0/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://webkit.org/blog/15865/webkit-features-in-safari-18-0/</a><a href=\\"https://spacejelly.dev/posts/mdx-in-nextjs\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://spacejelly.dev/posts/mdx-in-nextjs</a><p data-notion-block-id=\\"109e548d-8a8e-80ba-84f0-e72af98216fc\\">\uccab\ubc88\uc9f8\ub294 <code>Astro</code>\uac00 5\ubc84\uc804 \ubca0\ud0c0 \ub9b4\ub9ac\uc988\ud588\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4. \ud0c0\uc785 \uc548\uc815\uc131\uc744 \uac15\ud654\ud558\uace0 \ucee8\ud150\uce20\ub97c \uc798 \uac00\uc838\uc62c \uc218 \uc788\ub294 Content Layer\ub97c \ucd94\uac00\ud588\ub124\uc694. \ub450\ubc88\uc9f8 \uae00\uc740 Safari 18\ubc84\uc804 \ucd9c\uc2dc \uc18c\uc2dd\uc778\ub370, \\"\uc8fc\uc758 \uc81c\uc5b4 \uae30\ub2a5\\"(Distraction Control)\uc744 \uc8fc\ubaa9\ud560 \ub9cc\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ubaa8\ub2ec\ub85c \uc774\ubca4\ud2b8\ub97c \ub098\ud0c0\ub0b4\ub294 \uac74 \uc88b\uc740 UX\uac00 \uc544\ub2c8\ub2c8\uae4c\uc694. \uc138\ubc88\uc9f8 \uae00\uc740 <code>@next/mdx</code>\uac00 frontmatter\uc5d0 \ub300\ud55c \uc9c0\uc6d0\uc744 \ud558\uc9c0 \uc54a\ub294 \uac83\uc744 \uc18c\uac1c\ud558\uace0 \uc774\ub97c \ubcf4\uc644\ud55c \ub77c\uc774\ube0c\ub7ec\ub9ac\uc778 <code>next-mdx-remote</code>\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><p data-notion-block-id=\\"b384878b-7bbc-48ed-8614-d1b4e0a99d6a\\"></p>"}')}}]);